// Récupérer toutes les lignes FAQ de Google Sheets
const faqItems = $('Google Sheets - Lire FAQ').all();

// Construire le contexte FAQ formaté
let faqContext = 'BASE DE DONNÉES FAQ DU CABINET:\n\n';

for (const item of faqItems) {
  const row = item.json;
  const categorie = row['Catégorie'] || row['categorie'] || '';
  const question  = row['Question']  || row['question']  || '';
  const reponse   = row['Réponse']   || row['reponse']   || '';

  if (categorie && question && reponse) {
    faqContext += `Catégorie: ${categorie}\n`;
    faqContext += `Question: ${question}\n`;
    faqContext += `Réponse: ${reponse}\n\n`;
  }
}

return [{ json: { faqContext } }];

// Récupérer la sortie de l'AI Agent
const agentOutput = $input.first().json;

// L'AI Agent retourne le texte dans 'output'
const fullText = agentOutput.output || agentOutput.text || JSON.stringify(agentOutput);

// Séparer la réponse naturelle du bloc BOOKING
let chatResponse = fullText;
let hasBooking = false;
let booking = null;

// Regex pour extraire le bloc ---BOOKING---
const bookingMatch = fullText.match(/---BOOKING---([\s\S]*?)---BOOKING---/);

if (bookingMatch) {
  // Réponse texte = tout avant le premier ---BOOKING---
  chatResponse = fullText.split('---BOOKING---')[0].trim();
  const bookingText = bookingMatch[1];

  const typeMatch  = bookingText.match(/type:\s*(.+)/);
  const dateMatch  = bookingText.match(/date:\s*(.+)/);
  const timeMatch  = bookingText.match(/time:\s*(.+)/);
  const nameMatch  = bookingText.match(/name:\s*(.+)/);
  const phoneMatch = bookingText.match(/phone:\s*(.+)/);

  const bookingType = typeMatch ? typeMatch[1].trim() : 'null';

  if (bookingType && bookingType.toLowerCase() !== 'null' && bookingType !== '') {
    hasBooking = true;
    booking = {
      type:  bookingType,
      date:  dateMatch  ? dateMatch[1].trim()  : '',
      time:  timeMatch  ? timeMatch[1].trim()  : '',
      name:  nameMatch  ? nameMatch[1].trim()  : 'Patient',
      phone: phoneMatch ? phoneMatch[1].trim() : 'Non renseigné'
    };
  }
}

return [
  {
    json: {
      output: chatResponse,
      chatResponse,
      hasBooking,
      booking,
      bookingType:  booking ? booking.type  : null,
      bookingDate:  booking ? booking.date  : null,
      bookingTime:  booking ? booking.time  : null,
      bookingName:  booking ? booking.name  : null,
      bookingPhone: booking ? booking.phone : null
    }
  }
];

